def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 200:
                rich_opponents += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if not alive:
        return float(min(budget, 8.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / float(WATER_REQ)
    contested = units < 2.0
    very_tight = units < 1.5

    desperation = 0
    if hp <= 2:
        desperation += 3
    elif hp <= 4:
        desperation += 2
    elif hp <= 6:
        desperation += 1

    if no_water >= 2:
        desperation += 3
    elif no_water >= 1:
        desperation += 2

    if very_tight:
        desperation += 2
    elif contested:
        desperation += 1

    if urgent_opponents >= 2:
        desperation += 1

    if desperation >= 6:
        target = max(0.95 * DAILY_SALARY, highest_prev + 6.0)
    elif desperation >= 4:
        target = max(0.78 * DAILY_SALARY, avg_prev + 4.0, highest_prev * 0.72)
    elif desperation >= 2:
        if contested:
            target = max(0.52 * DAILY_SALARY, avg_prev + 2.0)
        else:
            target = max(0.34 * DAILY_SALARY, avg_prev * 0.7)
    else:
        if contested:
            target = max(0.28 * DAILY_SALARY, min(highest_prev * 0.55, 0.48 * DAILY_SALARY))
        else:
            target = max(0.12 * DAILY_SALARY, min(avg_prev * 0.4, 0.26 * DAILY_SALARY))

    if highest_prev >= 130 and desperation <= 2:
        target = min(target, 0.32 * DAILY_SALARY)

    if rich_opponents >= 2 and contested and desperation >= 3:
        target += 6.0

    if budget < DAILY_SALARY:
        target = min(target, max(8.0, budget * 0.55))
    elif budget < 2 * DAILY_SALARY:
        target = min(target, budget * 0.7)

    target = min(target, budget)
    if hp <= 2 or no_water >= 2:
        target = max(target, min(budget, 0.9 * DAILY_SALARY))

    if target < 0:
        target = 0.0

    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids to infer aggressiveness.
    yesterday_bids = []
    yesterday_by_agent = {}
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                continue
            yesterday_bids.append(b)
            yesterday_by_agent[oid] = b

    if yesterday_bids:
        max_bid_y = max(yesterday_bids)
        # Identify if Cindy was the top aggressor yesterday.
        cindy_bid = None
        for oid, b in yesterday_by_agent.items():
            if oid == 'Cindy':
                cindy_bid = b
                break
    else:
        max_bid_y = 0.0
        cindy_bid = None

    # Supply pressure: higher supply reduces need to overbid.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Urgency based on hp and no_water_days.
    urgency = 0.0
    if hp <= 2.0:
        urgency += 1.0
    elif hp <= 4.0:
        urgency += 0.6
    if no_water_days >= 2:
        urgency += 0.5
    if no_water_days >= 3:
        urgency += 0.7

    # Baseline bid: aim to win only when needed.
    # If we are in danger, bid closer to salary; otherwise bid mid.
    if urgency >= 1.0:
        base = DAILY_SALARY * (0.75 - 0.15 * supply_ratio)
    elif urgency >= 0.6:
        base = DAILY_SALARY * (0.6 - 0.1 * supply_ratio)
    else:
        base = DAILY_SALARY * (0.45 - 0.05 * supply_ratio)

    # Exploit yesterday: Cindy spiked; if she likely continues, slightly overcut her
    # but only when supply is not too low (so we can afford to contest).
    if cindy_bid is not None and supply >= (MIN_SUPPLY + (MAX_SUPPLY - MIN_SUPPLY) * 0.4):
        # If Cindy bid was very high yesterday, cap our aggression to avoid overspending.
        target = cindy_bid + 2.0
        cap = DAILY_SALARY * 0.85
        base = min(base, cap)
        base = max(base, target * 0.85)  # lean towards contesting

    # If yesterday max bid was extremely high, avoid matching unless we're urgent.
    if max_bid_y >= DAILY_SALARY * 1.3 and urgency < 0.6:
        base = min(base, DAILY_SALARY * 0.55)

    # Ensure bid is feasible.
    bid = min(budget, max(0.0, base))

    # If we have very low budget, bid proportionally.
    if budget <= DAILY_SALARY * 0.25:
        bid = min(bid, budget * 0.9)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid just enough to secure water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Collect yesterday's bids from all alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine highest previous bid to react to
    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Define thresholds for bidding based on HP and opponent behavior
    CRITICAL_HP_THRESHOLD = 3
    HIGH_BID_THRESHOLD = DAILY_SALARY * 0.85 # 127.5
    LOW_BID_SAVE_BUDGET = DAILY_SALARY * 0.3 # 45
    DESPERATE_BID = DAILY_SALARY * 0.95 # 142.5
    MODERATE_BASE_BID = DAILY_SALARY * 0.5 # 75

    # Strategy based on highest previous bid and my HP
    if highest_prev_bid >= HIGH_BID_THRESHOLD:
        # Opponent bid very high yesterday.
        if my_status['hp'] > CRITICAL_HP_THRESHOLD:
            # I'm not desperate, let them win this round to save budget.
            return min(my_status['budget'], LOW_BID_SAVE_BUDGET)
        else:
            # I'm desperate, must get water, bid aggressively.
            return min(my_status['budget'], DESPERATE_BID)
    else:
        # Opponents' previous bids were not excessively high.
        if my_status['hp'] <= CRITICAL_HP_THRESHOLD:
            # I'm desperate, bid high to secure water.
            return min(my_status['budget'], DESPERATE_BID)
        else:
            # Not desperate, bid strategically above the highest previous bid,
            # but ensure it's at least a moderate amount.
            # Add a small increment to ensure winning against a tie.
            return min(my_status['budget'], max(MODERATE_BASE_BID, highest_prev_bid + 1.5))

